  it('post200: locks src/genres.ts first/last/mid octets', () => { const d = sha256("src/genres.ts"); expect(d.slice(0, 2)).toBe("aa"); expect(d.slice(-2)).toBe("4e"); expect(d.slice(28, 36)).toBe("811dfbc2"); });
  it('post200: locks src/genres.ts HMAC post200/after-#200/leftover', () => { expect(hmacSha256('post200', "src/genres.ts")).toBe("487d8dc22151f5214bd1c78ca34cd9dd72a488ae9bde112a869984d84dc1ffd0"); expect(hmacSha256('after-#200', "src/genres.ts")).toBe("9ef342ff8781af87dcddc1fd1cee9dc69ebe27db2a6284d23d8d809af934ce06"); expect(hmacSha256('leftover', "src/genres.ts")).toBe("bc49b5523a2b049ad6ea2abd27732f8e53d9ff48d9296f3da0bd9cb76d72624f"); });
