  it('post200: locks src/genres.ts HMAC genres-mcp-spec-only/dual-surface/not-ci-config', () => { expect(hmacSha256('genres-mcp-spec-only', "src/genres.ts")).toBe("1dc55aa380681303ff111f28b7d7ff7954a152f41f7a226d94e60c571d33536d"); expect(hmacSha256('dual-surface', "src/genres.ts")).toBe("49b9d7a0709e6d5693e1c77a2fe7018471aba0a7661be165413ff76c9fb53f7a"); expect(hmacSha256('not-ci-config', "src/genres.ts")).toBe("308c856606e0e3922b89ed4c0434bd8592d98f654d61867ceb265b4e97ffed20"); });
