    expect(read("test/parser.test.ts").includes(['describe(', "'post241 mcp HEAVY deepen"].join(''))).toBe(false);
    expect(read(['test', 'routes.test.ts'].join('/')).includes(['describe(', "'post241 mcp HEAVY deepen"].join(''))).toBe(false);
    expect(read("test/genres.test.ts").includes(['describe(', "'post241 mcp HEAVY deepen"].join(''))).toBe(false);
