  it('post266: locks src/mcp.ts nibble 551 xor 1', () => { expect(nibbleSum(sha256("src/mcp.ts"))).toBe(551); expect(xorNibbles(sha256("src/mcp.ts"))).toBe(1); });
  it('post266: locks src/mcp.ts pairSum 4751 rollingXor 103', () => { expect(pairSum(sha256("src/mcp.ts"))).toBe(4751); expect(rollingXor(sha256("src/mcp.ts"))).toBe(103); });
  it('post266: locks src/mcp.ts first/last/mid octets', () => { expect(sha256("src/mcp.ts").slice(0, 2)).toBe("6a"); expect(sha256("src/mcp.ts").slice(-2)).toBe("83"); expect(sha256("src/mcp.ts").slice(32, 34)).toBe("1a"); });
  it('post266: locks src/mcp.ts HMAC post261/after-#266/leftover', () => { expect(hmacSha256("post266", "src/mcp.ts")).toBe("5825838dc9b298dd80ea7f617629f219c2ffc1d0c77d6e2365bc1360c6179e00"); expect(hmacSha256("after-#266", "src/mcp.ts")).toBe("8ebb0baeceb5d3a270c6b8fb6f144b94496a4a16c006b6c0da0bc8600a449d05"); expect(hmacSha256("leftover", "src/mcp.ts")).toBe("8ace2389ce0308341cb978ba9c33116db731b2166d09e0adc79fa37366b8c712"); });
  it('post266: locks src/mcp.ts HMAC TOKENMAXX/HEAVY/no-product-invent', () => { expect(hmacSha256("TOKENMAXX", "src/mcp.ts")).toBe("cc983fd02cae540665f120f8a72c3867b8d573a30f5a9c84ace5b4cea2fb9f62"); expect(hmacSha256("HEAVY", "src/mcp.ts")).toBe("870bb2f88c83abd6679e447c6937b01c998a1b3f527024e687dc35c00a046e40"); expect(hmacSha256("no-product-invent", "src/mcp.ts")).toBe("71a686fe812adcc92f40d5ca19a3996e68555d6749199affd3fc002053aabd65"); });
  it('post266: locks src/mcp.ts HMAC slice-diff/no-src-change/manifest-lock', () => { expect(hmacSha256("slice-diff", "src/mcp.ts")).toBe("4f4c0995596fa6a8eecfa27d7f7047b084074e0acf00d6890811a88f5f807e05"); expect(hmacSha256("no-src-change", "src/mcp.ts")).toBe("83880bdeca0f5e263ef18761f18cac15707d298b1c7fe1157e766221d37f343a"); expect(hmacSha256("manifest-lock", "src/mcp.ts")).toBe("b87b5d8230d2c0d160c1d3fd8e6864b8344b3765e2a3d5620130f45110a6c503"); });
  it('post266: locks src/mcp.ts HMAC genres-mcp-spec-only/dual-surface/not-parser-routes', () => { expect(hmacSha256("genres-mcp-spec-only", "src/mcp.ts")).toBe("c7c928169f387e60bfce37066b7c48f68ddeb63c93f67ca0298f484b81c6750a"); expect(hmacSha256("dual-surface", "src/mcp.ts")).toBe("c0a7339db32bc527f28312bd2a932f0fd759edea4ab2824123c3f8254a866562"); expect(hmacSha256("not-parser-routes", "src/mcp.ts")).toBe("147fac5c4fd100828fed5a611bece23fa04ccbe0ae5150d092897fba3f2bd805"); });
  it('post266: locks src/mcp.ts HMAC utf16-js-length/residual-edges/after-merged-266', () => { expect(hmacSha256("utf16-js-length", "src/mcp.ts")).toBe("d9ecf981917f345d774f9a82b8f367fdee5948421f12c574538418440718dcf7"); expect(hmacSha256("residual-edges", "src/mcp.ts")).toBe("72e6de7f088b5f94a3d2857bcfd8f5186e4857abdd404e53f7af872cbe5228e7"); expect(hmacSha256("after-merged-266", "src/mcp.ts")).toBe("743628644e2bedfc545be9cca876d94b5340c76fd59007f7a957e04743cac6d3"); });
  it('post266: locks src/mcp.ts HMAC unsaturated-after-266/helpers-source-merged-265/beyond-post261', () => { expect(hmacSha256("unsaturated-after-266", "src/mcp.ts")).toBe("3609a992474f210a56ccc78af9c36a7932ba81cfb8c51f44931f0e1af54d1853"); expect(hmacSha256("helpers-source-merged-265", "src/mcp.ts")).toBe("44181608cf58aeb599420355f54a1bc67f11741992ac6b3d4c8b49bb9cd2e157"); expect(hmacSha256("beyond-post261", "src/mcp.ts")).toBe("f87c7e6d1a928fc0826f89ae1c9f5612e7a9af6411e4f26da84880caea224b72"); });
