  it('post266: locks src/mcp.ts HMAC after-#262/after-#256/not-wrangler', () => { expect(hmacSha256("after-#262", "src/mcp.ts")).toBe("069bdaefd027ad2152c6f687466ef507d652a719c729192c609fc9c5a127caed"); expect(hmacSha256("after-#256", "src/mcp.ts")).toBe("1612b5153c61bb53a7faa9893efcac23f18d0a99f82e652dd45bf52160e9b166"); expect(hmacSha256("not-wrangler", "src/mcp.ts")).toBe("19da8c70763bc4d090ae8cfec9b1270d16fe020786de44aa9edddf37f734e83a"); });
