  it('post268-extras: nibble src/mcp.ts', () => { expect(nibbleSum(sha256("src/mcp.ts"))).toBe(551); });
  it('post268-extras: pairSum src/mcp.ts', () => { const hex=sha256("src/mcp.ts"); let s=0; for(let i=0;i<hex.length;i+=2) s+=parseInt(hex.slice(i,i+2),16); expect(s).toBe(4751); });
  it('post268-extras: rollingXor src/mcp.ts', () => { const hex=sha256("src/mcp.ts"); let a=0; for(let i=0;i<hex.length;i+=2) a^=parseInt(hex.slice(i,i+2),16); expect(a).toBe(103); });
  it('post268-extras: spaces src/mcp.ts', () => { expect((read("src/mcp.ts").match(/ /g) ?? []).length).toBe(617); });
  it('post268-extras: code-unit src/mcp.ts', () => { expect([...read("src/mcp.ts")].reduce((s,c)=>s+c.codePointAt(0)!,0)).toBe(155333); });
