  it('post302-extras: rollingXor src/mcp.ts', () => { const hex=sha256("src/mcp.ts"); let a=0; for(let i=0;i<hex.length;i+=2) a^=parseInt(hex.slice(i,i+2),16); expect(a).toBe(103); });
  it('post302-extras: spaces src/mcp.ts', () => { expect((read("src/mcp.ts").match(/ /g) ?? []).length).toBe(617); });
