  it('post308-ultra: concat-sha tip-relaunch-leftover src/types.ts', () => { expect(createHash('sha256').update(Buffer.concat([readFileSync(join(repo, "src/types.ts")), Buffer.from("tip-relaunch-leftover")])).digest('hex')).toBe("a10084ccc7acf32b2f072ee0a91208f68ec6f466924f4328532ab5c5b5710963"); });
