  it('post308-ultra: concat-sha after-merged-308 src/types.ts', () => { expect(createHash('sha256').update(Buffer.concat([readFileSync(join(repo, "src/types.ts")), Buffer.from("after-merged-308")])).digest('hex')).toBe("ee7af49407c8708fae80aea418ac1b3cbf767d7f35b52961345c3b3f45ec6778"); });
